namespace App\Services\News;
use App\Models\NewsSource;use Illuminate\Support\Facades\Http;
class RssNewsFetcher{public function __construct(private SourceUrlGuard $guard,private NewsNormalizerService $normalizer){}public function fetch(NewsSource $source):array{if(!$source->feed_url)return [];$this->guard->assertAllowed($source->feed_url);$response=Http::accept('application/rss+xml, application/atom+xml, application/xml')->withHeaders(['User-Agent'=>'AscendiaNewsBot/1.0 (+'.config('app.url').')'])->connectTimeout(5)->timeout(20)->retry(3,500)->withOptions(['allow_redirects'=>['max'=>2,'strict'=>true]])->get($source->feed_url)->throw();$body=$response->body();if(strlen($body)>config('news.max_feed_bytes'))throw new \RuntimeException("Feed exceeds maximum size: {$source->name}");libxml_use_internal_errors(true);$xml=simplexml_load_string($body,'SimpleXMLElement',LIBXML_NONET|LIBXML_NOCDATA);if(!$xml)throw new \RuntimeException("Invalid RSS/XML response: {$source->name}");$nodes=$xml->channel->item??$xml->entry??[];$items=[];foreach($nodes as $node){$media=$node->children('media',true);$raw=['title'=>(string)$node->title,'url'=>(string)($node->link['href']??$node->link),'description'=>(string)($node->description??$node->summary??$node->content),'published_at'=>(string)($node->pubDate??$node->published??$node->updated),'image'=>(string)($media->content['url']??$media->thumbnail['url']??''),'author'=>(string)($node->author->name??$node->author)];if($item=$this->normalizer->normalize($raw,$source))$items[]=$item;}return $items;}}
